 if(type==='day'){const week=$('.week'),buttons=[...week.querySelectorAll('[data-day]')],from=week.querySelector('.selected'),to=buttons.find(b=>b.dataset.day===changes.day)||buttons[(new Date(changes.day+'T12:00:00').getDay()+6)%7];if(from&&to){const r=from.getBoundingClientRect(),t=to.getBoundingClientRect(),w=week.getBoundingClientRect(),el=document.createElement('span');el.className='week-marker';el.setAttribute('aria-hidden','true');Object.assign(el.style,{left:r.left-w.left+'px',top:r.top-w.top+'px',width:r.width+'px',height:r.height+'px'});week.classList.add('selection-moving');week.append(el);indicator={el,week,delta:t.left-r.left,from,to};}}
