 function beginReorder(p){if(pan!==p||p.active||!p.surface.isConnected)return;clearDragSelection();p.type='reorder';p.active=true;p.group=p.surface.parentElement;const r=p.surface.getBoundingClientRect();p.offset=p.y-r.top;p.ghost=p.surface.cloneNode(true);p.ghost.classList.add('drag-ghost');p.ghost.removeAttribute('data-row');p.ghost.setAttribute('aria-hidden','true');Object.assign(p.ghost.style,{left:r.left+'px',top:r.top+'px',width:r.width+'px'});root.append(p.ghost);p.surface.classList.add('reordering');root.classList.add('reorder-active');root.setPointerCapture?.(p.pointerId);navigator.vibrate?.(12);}
 function moveReorder(p,y){p.ghost.style.top=(y-p.offset)+'px';let target=document.elementFromPoint(p.x,y)?.closest('[data-row]');while(target&&target.parentElement!==p.group)target=target.parentElement?.closest('[data-row]');if(target&&target!==p.surface&&target.parentElement===p.group&&!get(target.dataset.row)?.done){const r=target.getBoundingClientRect();if(y>r.top+r.height/2)target.after(p.surface);else target.before(p.surface);}const bottom=$('nav')?.getBoundingClientRect().top||innerHeight;if(y>bottom-45)window.scrollBy(0,12);else if(y<90)window.scrollBy(0,-12);}
 async function finishReorder(p){clearTimeout(p.hold);if(root.hasPointerCapture?.(p.pointerId))root.releasePointerCapture(p.pointerId);const ids=[...p.group.querySelectorAll(':scope > [data-row]')].map(n=>n.dataset.row).filter(id=>['task','goal'].includes(get(id)?.kind)&&!get(id)?.done&&!get(id)?.closed);endReorder(p);ui.lastSwipe=Date.now();await perform(ids.map((id,i)=>({id,kind:get(id).kind,patch:{order:i+1}})),'Порядок сохранён');}
