 function paintTaskHint(p,dx){if(!p.hint){const h=document.createElement('div');h.className='task-swipe-hint';h.setAttribute('aria-hidden','true');p.surface.parentNode.insertBefore(h,p.surface);p.hint=h;}const r=p.surface.getBoundingClientRect();p.hint.style.height=r.height+'px';p.hint.style.marginBottom=-r.height+'px';p.hint.classList.toggle('to-left',dx<0);p.hint.innerHTML=dx>0?icon('move',18)+'<span>Перенести</span>':icon(taskFlag(get(p.id))||'diamond',13)+'<span>Обозначить</span>';p.hint.style.opacity=String(Math.min(1,Math.abs(dx)/65));}
 async function cancelPan(p){clearTimeout(p.hold);if(p.type==='reorder'){endReorder(p);render();return;}p.hint?.remove();if(p.motion){ui.animating=true;try{await p.motion.finish(false);}finally{p.motion.dispose();ui.animating=false;if(ui.renderPending)render();}}else if(p.surface){const from=p.surface.style.transform;p.surface.style.transform='';if(from)p.surface.animate([{transform:from},{transform:'translate3d(0,0,0)'}],{duration:220,easing:'cubic-bezier(.22,.72,.18,1)'});if(ui.renderPending)render();}}
 root.addEventListener('pointerup',async e=>{if(!pan||e.pointerId!==pan.pointerId)return;const p=pan;pan=null;clearTimeout(p.hold);if(p.type==='reorder'){await finishReorder(p);return;}const dx=e.clientX-p.x,dy=e.clientY-p.y;if(root.hasPointerCapture?.(e.pointerId))root.releasePointerCapture(e.pointerId);if(!p.active)return;ui.lastSwipe=Date.now();if(p.type==='task'){if(Math.abs(dx)<65||Math.abs(dx)<Math.abs(dy)*1.5){await cancelPan(p);return;}await cancelPan(p);if(!get(p.id))return;if(dx>0)openTransfer(p.id);else{const t=get(p.id);if(t?.kind==='shopping'){ui.actionId=t.id;render();}else if(t?.kind==='task')editTaskFlag(t.id);}return;}const signed=-p.direction*dx,width=p.motion?.width||innerWidth,commit=signed>width*.24||(signed>30&&-p.direction*p.velocity>.35);if(!commit){await cancelPan(p);return;}await slideTo(p.type,p.direction,p.changes,p.type==='back'?()=>ui.history.pop():null,p.motion);});
